// key is process-private randomness; cursors never need to survive a restart.
var changeCursorSigningKey = newChangeCursorSigningKey()

func newChangeCursorSigningKey() []byte {
	key := make([]byte, 32)
	if _, err := rand.Read(key); err != nil {
