	if err := json.Unmarshal(payload, &cursor); err != nil {
		return changeCursorPos{}, false
	}
	if cursor.Filter != expected {
		return changeCursorPos{}, false
	}
	if cursor.Pos.RecordedAt == "" || cursor.Pos.RecordID <= 0 || cursor.Pos.Sequence <= 0 ||
		cursor.Pos.Title == "" {
		return changeCursorPos{}, false
	}
	return cursor.Pos, true
}

