package store

import (
	"database/sql"
	"fmt"
	"sort"
	"strings"
)

// Error codes introduced for the gate-evaluation API. Values are stable
// public identifiers returned verbatim in error responses.
const (
	CodeGateEvaluationConflict          = "GATE_EVALUATION_CONFLICT"
	CodeGateEvaluationValidationFailed  = "GATE_EVALUATION_VALIDATION_FAILED"
	CodeGateStatusMismatch              = "GATE_STATUS_MISMATCH"
	CodeGateEvaluationNotFoundV1        = "GATE_EVALUATION_NOT_FOUND"
	CodeInvalidGateEvaluationQueryV1    = "INVALID_GATE_EVALUATION_QUERY"
)

// Gate check status values accepted on input and stored verbatim.
const (
	GateCheckPassed  = "passed"
	GateCheckFailed  = "failed"
	GateCheckWaived  = "waived"
	GateCheckPending = "pending"
)

// GateCheck is one immutable gate verdict belonging to one gate evaluation.
type GateCheck struct {
	CheckName    string
	Status       string
	Evidence     string
	WaiverReason string
}

// GateEvaluation is the immutable snapshot explaining one release record's
// gate_status through its individual checks.
type GateEvaluation struct {
	RecordID            int64
	ReleaseRecordID     string
	Environment         string
	Version             string
	BatchID             string
	GateStatus          string
	EffectiveGateStatus string
	RecordedAt          string
	Checks              []GateCheck
}

// GateEvaluationFilter narrows ListGateEvaluationsPage. Zero-valued fields
// are ignored. CheckStatus matches evaluations containing at least one check
// with that status.
type GateEvaluationFilter struct {
	Environment string
	Version     string
	GateStatus  string
	CheckStatus string
}

// Gate evaluation storage errors. They carry no stored snapshot; callers
// resolve the existing snapshot separately when the response needs it.

// ErrGateEvaluationMissing marks a release record that has no evaluation.
type ErrGateEvaluationMissing struct {
	PublicID string
}

func (e *ErrGateEvaluationMissing) Error() string {
	return "gate evaluation for release record " + e.PublicID + " does not exist"
}

// ErrReleaseRecordMissing marks an unknown release record public id.
type ErrReleaseRecordMissing struct {
	PublicID string
}

func (e *ErrReleaseRecordMissing) Error() string {
	return "release record " + e.PublicID + " does not exist"
}

// ErrGateEvaluationConflict marks a second submission whose checks differ
// from the immutable snapshot already stored for the release record.
type ErrGateEvaluationConflict struct {
	PublicID string
}

func (e *ErrGateEvaluationConflict) Error() string {
	return "gate evaluation for release record " + e.PublicID + " already exists with different checks"
}

// ErrGateStatusMismatch marks checks whose effective status does not equal
// the release record's stored gate_status.
type ErrGateStatusMismatch struct {
	PublicID  string
	Expected  string
	Effective string
}

func (e *ErrGateStatusMismatch) Error() string {
	return "gate checks derive " + e.Effective + " but release record gate_status is " + e.Expected
}

// DeriveGateStatus reduces individual check statuses to the effective release
// gate status: any failed check blocks, otherwise any pending check leaves the
// gate pending, otherwise the gate is allowed.
func DeriveGateStatus(checks []GateCheck) string {
	effective := "allowed"
	for _, check := range checks {
		if check.Status == GateCheckFailed {
			return "blocked"
		}
		if check.Status == GateCheckPending {
			effective = "pending"
		}
	}
	return effective
}

// SaveGateEvaluation atomically stores the immutable evaluation for one
// release record. The first submission inserts the snapshot inside one
// transaction (existence checks, gate_status verification and all check
// rows) and returns created == true. A repeated submission with the same
// checks returns the stored snapshot and created == false; a repeated
// submission with different checks returns *ErrGateEvaluationConflict.
//
// Unknown records yield *ErrReleaseRecordMissing; checks deriving a status
// different from the record's gate_status yield *ErrGateStatusMismatch and
// leave no partial rows behind.
func (s *Store) SaveGateEvaluation(publicID string, checks []GateCheck) (*GateEvaluation, bool, error) {
	tx, err := s.db.Begin()
	if err != nil {
		return nil, false, fmt.Errorf("store: begin gate evaluation tx: %w", err)
	}
	committed := false
	defer func() {
		if !committed {
			_ = tx.Rollback()
		}
	}()

	var recordID int64
	var environment, version, batchID, gateStatus, recordedAt string
	err = tx.QueryRow(
		`SELECT id, environment, version, batch_id, gate_status, recorded_at
		 FROM release_records WHERE public_id = ?`,
		publicID,
	).Scan(&recordID, &environment, &version, &batchID, &gateStatus, &recordedAt)
	if err == sql.ErrNoRows {
		return nil, false, &ErrReleaseRecordMissing{PublicID: publicID}
	}
	if err != nil {
		return nil, false, fmt.Errorf("store: load release record for gate evaluation: %w", err)
	}

	effective := DeriveGateStatus(checks)
	if effective != gateStatus {
		return nil, false, &ErrGateStatusMismatch{
			PublicID:  publicID,
			Expected:  gateStatus,
			Effective: effective,
		}
	}

	var existingID int64
	err = tx.QueryRow(
		`SELECT id FROM gate_evaluations WHERE record_id = ?`, recordID,
	).Scan(&existingID)
	switch {
	case err == nil:
		existingChecks, queryErr := queryGateChecksTx(tx, existingID)
		if queryErr != nil {
			return nil, false, queryErr
		}
		if !sameGateChecks(existingChecks, checks) {
			return nil, false, &ErrGateEvaluationConflict{PublicID: publicID}
		}
		evaluation := &GateEvaluation{
			RecordID:            recordID,
			ReleaseRecordID:     publicID,
			Environment:         environment,
			Version:             version,
			BatchID:             batchID,
			GateStatus:          gateStatus,
			EffectiveGateStatus: effective,
			RecordedAt:          recordedAt,
			Checks:              existingChecks,
		}
		return evaluation, false, nil
	case err != sql.ErrNoRows:
		return nil, false, fmt.Errorf("store: check existing gate evaluation: %w", err)
	}

	result, err := tx.Exec(
		`INSERT INTO gate_evaluations (record_id) VALUES (?)`, recordID,
	)
	if err != nil {
		return nil, false, fmt.Errorf("store: insert gate evaluation: %w", err)
	}
	evaluationID, err := result.LastInsertId()
	if err != nil {
		return nil, false, fmt.Errorf("store: insert gate evaluation: %w", err)
	}
	for _, check := range checks {
		if _, err := tx.Exec(
			`INSERT INTO gate_evaluation_checks
			   (evaluation_id, check_name, status, evidence, waiver_reason)
			 VALUES (?, ?, ?, ?, ?)`,
			evaluationID, check.CheckName, check.Status, check.Evidence, check.WaiverReason,
		); err != nil {
			return nil, false, fmt.Errorf("store: insert gate evaluation check: %w", err)
		}
	}
	if err := tx.Commit(); err != nil {
		return nil, false, fmt.Errorf("store: commit gate evaluation: %w", err)
	}
	committed = true

	storedChecks := append([]GateCheck(nil), checks...)
	sortGateChecks(storedChecks)
	evaluation := &GateEvaluation{
		RecordID:            recordID,
		ReleaseRecordID:     publicID,
		Environment:         environment,
		Version:             version,
		BatchID:             batchID,
		GateStatus:          gateStatus,
		EffectiveGateStatus: effective,
		RecordedAt:          recordedAt,
		Checks:              storedChecks,
	}
	return evaluation, true, nil
}

// GetGateEvaluation returns the snapshot attached to one release record. An
// unknown record yields *ErrReleaseRecordMissing; a record without a snapshot
// yields *ErrGateEvaluationMissing.
func (s *Store) GetGateEvaluation(publicID string) (*GateEvaluation, error) {
	var evaluationID, recordID int64
	var public string
	var environment, version, batchID, gateStatus, recordedAt string
	err := s.db.QueryRow(
		`SELECT g.id, r.id, r.public_id, r.environment, r.version, r.batch_id,
		        r.gate_status, r.recorded_at
		 FROM gate_evaluations g
		 JOIN release_records r ON r.id = g.record_id
		 WHERE r.public_id = ?`,
		publicID,
	).Scan(&evaluationID, &recordID, &public, &environment, &version, &batchID,
		&gateStatus, &recordedAt)
	if err == sql.ErrNoRows {
		exists, checkErr := s.releaseRecordExists(publicID)
		if checkErr != nil {
			return nil, checkErr
		}
		if !exists {
			return nil, &ErrReleaseRecordMissing{PublicID: publicID}
		}
		return nil, &ErrGateEvaluationMissing{PublicID: publicID}
	}
	if err != nil {
		return nil, fmt.Errorf("store: get gate evaluation: %w", err)
	}
	checks, err := s.queryGateChecks(evaluationID)
	if err != nil {
		return nil, err
	}
	return &GateEvaluation{
		RecordID:            recordID,
		ReleaseRecordID:     public,
		Environment:         environment,
		Version:             version,
		BatchID:             batchID,
		GateStatus:          gateStatus,
		EffectiveGateStatus: DeriveGateStatus(checks),
		RecordedAt:          recordedAt,
		Checks:              checks,
	}, nil
}

// ListGateEvaluationsPage returns one keyset page of snapshots matching the
// filter, newest first by release record recorded_at descending and internal
// record id descending for same-second ties. The anchor marks the last
// snapshot already returned; zero anchor values request the first page. Up
// to limit+1 rows are fetched so the caller can detect a following page.
func (s *Store) ListGateEvaluationsPage(
	filter GateEvaluationFilter,
	anchorRecordedAt string,
	anchorID int64,
	limit int,
) ([]GateEvaluation, error) {
	where := []string{`g.record_id IS NOT NULL`}
	args := []any{}
	if filter.Environment != "" {
		where = append(where, `r.environment = ?`)
		args = append(args, filter.Environment)
	}
	if filter.Version != "" {
		where = append(where, `r.version = ?`)
		args = append(args, filter.Version)
	}
	if filter.GateStatus != "" {
		where = append(where, `r.gate_status = ?`)
		args = append(args, filter.GateStatus)
	}
	if filter.CheckStatus != "" {
		where = append(where,
			`EXISTS (SELECT 1 FROM gate_evaluation_checks c
			         WHERE c.evaluation_id = g.id AND c.status = ?)`)
		args = append(args, filter.CheckStatus)
	}
	if anchorID > 0 {
		where = append(where, `(r.recorded_at < ? OR (r.recorded_at = ? AND r.id < ?))`)
		args = append(args, anchorRecordedAt, anchorRecordedAt, anchorID)
	}
	query := `SELECT g.id, r.id, r.public_id, r.environment, r.version, r.batch_id,
	                 r.gate_status, r.recorded_at
	          FROM gate_evaluations g
	          JOIN release_records r ON r.id = g.record_id
	          WHERE ` + strings.Join(where, ` AND `) + `
	          ORDER BY r.recorded_at DESC, r.id DESC
	          LIMIT ?`
	args = append(args, limit+1)

	rows, err := s.db.Query(query, args...)
	if err != nil {
		return nil, fmt.Errorf("store: list gate evaluations: %w", err)
	}
	evaluations := []GateEvaluation{}
	for rows.Next() {
		var evaluation GateEvaluation
		var evaluationID int64
		if err := rows.Scan(
			&evaluationID, &evaluation.RecordID, &evaluation.ReleaseRecordID,
			&evaluation.Environment, &evaluation.Version, &evaluation.BatchID,
			&evaluation.GateStatus, &evaluation.RecordedAt,
		); err != nil {
			rows.Close()
			return nil, fmt.Errorf("store: scan gate evaluation: %w", err)
		}
		checks, err := s.queryGateChecks(evaluationID)
		if err != nil {
			rows.Close()
			return nil, err
		}
		evaluation.EffectiveGateStatus = DeriveGateStatus(checks)
		evaluation.Checks = checks
		evaluations = append(evaluations, evaluation)
	}
	if err := rows.Close(); err != nil {
		return nil, fmt.Errorf("store: list gate evaluations: %w", err)
	}
	return evaluations, nil
}

// ResolveGateEvaluationPosition maps a record's stable public identifier to
// its internal keyset position (recorded_at, internal record id). Snapshot
// rows are immutable, so a resolved position keeps pointing at the same
// evaluation. It returns ok == false when the record has no evaluation.
func (s *Store) ResolveGateEvaluationPosition(publicID string) (recordedAt string, id int64, ok bool, err error) {
	err = s.db.QueryRow(
		`SELECT r.recorded_at, r.id
		 FROM release_records r
		 JOIN gate_evaluations g ON g.record_id = r.id
		 WHERE r.public_id = ?`,
		publicID,
	).Scan(&recordedAt, &id)
	if err == sql.ErrNoRows {
		return "", 0, false, nil
	}
	if err != nil {
		return "", 0, false, fmt.Errorf("store: resolve gate evaluation position: %w", err)
	}
	return recordedAt, id, true, nil
}

func (s *Store) releaseRecordExists(publicID string) (bool, error) {
	var count int
	if err := s.db.QueryRow(
		`SELECT count(1) FROM release_records WHERE public_id = ?`, publicID,
	).Scan(&count); err != nil {
		return false, fmt.Errorf("store: check release record: %w", err)
	}
	return count > 0, nil
}

func (s *Store) queryGateChecks(evaluationID int64) ([]GateCheck, error) {
	rows, err := s.db.Query(
		`SELECT check_name, status, evidence, waiver_reason
		 FROM gate_evaluation_checks WHERE evaluation_id = ?
		 ORDER BY check_name ASC, id ASC`,
		evaluationID,
	)
	if err != nil {
		return nil, fmt.Errorf("store: query gate evaluation checks: %w", err)
	}
	defer rows.Close()
	return scanGateChecks(rows)
}

func queryGateChecksTx(tx *sql.Tx, evaluationID int64) ([]GateCheck, error) {
	rows, err := tx.Query(
		`SELECT check_name, status, evidence, waiver_reason
		 FROM gate_evaluation_checks WHERE evaluation_id = ?
		 ORDER BY check_name ASC, id ASC`,
		evaluationID,
	)
	if err != nil {
		return nil, fmt.Errorf("store: query gate evaluation checks: %w", err)
	}
	defer rows.Close()
	return scanGateChecks(rows)
}

func scanGateChecks(rows *sql.Rows) ([]GateCheck, error) {
	checks := []GateCheck{}
	for rows.Next() {
		var check GateCheck
		if err := rows.Scan(&check.CheckName, &check.Status, &check.Evidence, &check.WaiverReason); err != nil {
			return nil, fmt.Errorf("store: scan gate evaluation check: %w", err)
		}
		checks = append(checks, check)
	}
	if err := rows.Err(); err != nil {
		return nil, fmt.Errorf("store: query gate evaluation checks: %w", err)
	}
	return checks, nil
}

