// DeriveGateStatus explains a release record's gate_status from its checks:
// any failed check blocks the gate; without a failure, any pending check
// leaves it pending; otherwise the gate is allowed. Waived and passed checks
// never block.
func DeriveGateStatus(checks []GateCheck) string {
	effective := "allowed"
	for _, check := range checks {
		switch check.CheckStatus {
		case GateCheckFailed:
			return "blocked"
		case GateCheckPending:
			effective = "pending"
		}
	}
	return effective
