}

// sameGateChecks compares two check sets as sets keyed by check_name. Both
// slices are read in canonical (check_name ascending) order.
func sameGateChecks(existing, submitted []GateCheck) bool {
	if len(existing) != len(submitted) {
		return false
	}
	canonical := make([]GateCheck, len(submitted))
	copy(canonical, submitted)
	sortGateChecks(canonical)
	for i := range existing {
		if existing[i] != canonical[i] {
			return false
		}
	}
	return true
}

