// gateEvaluationChecksEqualTx reports whether the checks stored on the
// snapshot equal the submitted, already check-name-sorted checks.
func gateEvaluationChecksEqualTx(tx *sql.Tx, evaluationID int64, checks []GateCheck) (bool, error) {
	rows, err := tx.Query(
		`SELECT check_name, status, evidence, waiver_reason
		 FROM release_gate_checks WHERE evaluation_id = ?
