// Error codes for the public gate-evaluation snapshots.
const (
	CodeGateEvaluationConflictV1     = "GATE_EVALUATION_CONFLICT"
	CodeGateEvaluationNotFoundV1     = "GATE_EVALUATION_NOT_FOUND"
