// GateCheckStatus enumerates the immutable states one public gate check may
// be reported with.
const (
	GateCheckPassed  = "passed"
	GateCheckFailed  = "failed"
	GateCheckWaived  = "waived"
	GateCheckPending = "pending"
)

var validGateCheckStatuses = map[string]bool{
	GateCheckPassed:  true,
	GateCheckFailed:  true,
	GateCheckWaived:  true,
	GateCheckPending: true,
}

// ValidGateCheckStatus reports whether status is one of the four accepted
// check states.
func ValidGateCheckStatus(status string) bool {
	return validGateCheckStatuses[status]
}

// GateCheck is one immutable gate check captured by a gate-evaluation
// snapshot.
type GateCheck struct {
	CheckName    string
	Status       string
	Evidence     string
	WaiverReason string
}

// GateEvaluation is the immutable public snapshot that explains a release
// record's gate status. Exactly one snapshot exists per release record.
type GateEvaluation struct {
	RecordID            int64
	ReleaseRecordID     string
	Environment         string
	Version             string
	BatchID             string
	GateStatus          string
	EffectiveGateStatus string
	Checks              []GateCheck
	RecordedAt          string
