// GateEvaluationFilter narrows ListGateEvaluationsPage. Empty fields are
// ignored. CheckStatus matches evaluations containing at least one check in
// that state.
type GateEvaluationFilter struct {
	Environment string
	Version     string
	GateStatus  string
	CheckStatus string
}

// ErrReleaseRecordMissing marks a save against a release record that does
// not exist.
type ErrReleaseRecordMissing struct {
	PublicID string
}

func (e *ErrReleaseRecordMissing) Error() string {
	return "release record " + e.PublicID + " does not exist"
}

// ErrGateEvaluationExists marks a second, different snapshot submission for
// a release record that already carries an immutable snapshot.
type ErrGateEvaluationExists struct {
	PublicID string
}

func (e *ErrGateEvaluationExists) Error() string {
	return "gate evaluation for release record " + e.PublicID + " already exists"
}

// ErrGateStatusMismatch marks a derived effective gate status that disagrees
// with the gate status stored on the release record.
type ErrGateStatusMismatch struct {
	PublicID        string
	RecordGate      string
	EffectiveStatus string
}

func (e *ErrGateStatusMismatch) Error() string {
	return "gate evaluation derives " + e.EffectiveStatus +
		" but release record " + e.PublicID + " records " + e.RecordGate
}

// DeriveGateStatus reduces public check states to the effective release gate
// status: any failed check blocks, otherwise a pending check leaves the gate
// pending, otherwise the release is allowed.
func DeriveGateStatus(checks []GateCheck) string {
	hasPending := false
	for _, check := range checks {
		switch check.Status {
		case GateCheckFailed:
			return "blocked"
		case GateCheckPending:
			hasPending = true
		}
	}
	if hasPending {
		return "pending"
	}
	return "allowed"
}

