func (s *Store) SaveGateEvaluation(publicID string, checks []GateCheck) (evaluation *GateEvaluation, created bool, err error) {
	tx, err := s.db.Begin()
	if err != nil {
		return nil, false, fmt.Errorf("store: begin gate evaluation tx: %w", err)
