package v1

import (
	"net/http"
	"testing"

	"github.com/gin-gonic/gin"
)

func gateEvaluationBody(checks string) string {
	return `{"checks":[` + checks + `]}`
}

func createGateEvaluationOK(t *testing.T, router *gin.Engine, recordID, checks string) map[string]any {
	t.Helper()
	recorder := doRequest(t, router, http.MethodPost,
		"/api/v1/release-records/"+recordID+"/gate-evaluations", gateEvaluationBody(checks))
	if recorder.Code != http.StatusCreated {
		t.Fatalf("create gate evaluation status = %d, want 201 (body %s)", recorder.Code, recorder.Body.String())
	}
	body := decodeBody(t, recorder)
	evaluation, ok := body["gate_evaluation"].(map[string]any)
	if !ok || len(body) != 1 {
		t.Fatalf("response must contain only gate_evaluation: %s", recorder.Body.String())
	}
	return evaluation
}

func recordBodyWithGate(environment, version, gate string) string {
	return `{"environment":"` + environment + `","version":"` + version + `",
	  "changes":[{"sequence":1,"category":"feature","title":"base","description":"base"}],
	  "gate_status":"` + gate + `","rollback_point":"rb:` + version + `"}`
}

func assertCheckNames(t *testing.T, evaluation map[string]any, want []string) {
	t.Helper()
	rawChecks, ok := evaluation["checks"].([]any)
	if !ok {
		t.Fatalf("checks not an array: %v", evaluation["checks"])
	}
	if len(rawChecks) != len(want) {
		t.Fatalf("checks len = %d, want %d", len(rawChecks), len(want))
	}
	for i, raw := range rawChecks {
		check := raw.(map[string]any)
		if check["check_name"] != want[i] {
			t.Fatalf("checks[%d] = %v, want name %q", i, check, want[i])
		}
	}
}

func TestCreateGateEvaluationSnapshot(t *testing.T) {
	router := newTestRouter(t)
	registerEnvironmentOK(t, router, "prod")
	record := createRecordOK(t, router, recordBodyWithGate("prod", "1.0.0", "blocked"))
	recordID := record["id"].(string)

	evaluation := createGateEvaluationOK(t, router, recordID,
		`{"check_name":"zeta","status":"passed","evidence":"z"},
		 {"check_name":"alpha","status":"failed","evidence":"a"},
		 {"check_name":"mid","status":"waived","evidence":"m","waiver_reason":"known risk"}`)

	if evaluation["release_record_id"] != recordID {
		t.Fatalf("release_record_id = %v", evaluation["release_record_id"])
	}
	if evaluation["environment"] != "prod" || evaluation["version"] != "1.0.0" {
		t.Fatalf("locator mismatch: %v", evaluation)
	}
	if evaluation["gate_status"] != "blocked" || evaluation["effective_gate_status"] != "blocked" {
		t.Fatalf("statuses = %v/%v", evaluation["gate_status"], evaluation["effective_gate_status"])
	}
	if _, present := evaluation["batch_id"]; present {
		t.Fatalf("batch_id must be omitted for unbatched record: %v", evaluation)
	}
	assertCheckNames(t, evaluation, []string{"alpha", "mid", "zeta"})
	body := mustGetGateEvaluation(t, router, recordID)
	assertCheckNames(t, body, []string{"alpha", "mid", "zeta"})
}

func mustGetGateEvaluation(t *testing.T, router *gin.Engine, recordID string) map[string]any {
	t.Helper()
	recorder := doRequest(t, router, http.MethodGet,
		"/api/v1/release-records/"+recordID+"/gate-evaluations", "")
	if recorder.Code != http.StatusOK {
		t.Fatalf("get gate evaluation status = %d (body %s)", recorder.Code, recorder.Body.String())
	}
	return decodeBody(t, recorder)["gate_evaluation"].(map[string]any)
}

func TestCreateGateEvaluationIdempotentAndConflict(t *testing.T) {
	router := newTestRouter(t)
	registerEnvironmentOK(t, router, "prod")
	record := createRecordOK(t, router, recordBodyWithGate("prod", "1.0.0", "pending"))
